/* CLEJS Theme - Modular extensions for JumpStart 3D */
/* Harmonized with JumpStart CSS variables: --paper, --panel, --ink, --block, --accent */

.cle-top-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: var(--on-accent);
  border: 1px solid var(--line);
  border-radius: var(--r);
  padding: 4px 10px;
  font: 600 12px/1 var(--f-ui);
  cursor: pointer;
  margin-left: 8px;
  transition: background 0.15s ease, transform 0.1s ease;
}
.cle-top-btn:hover {
  background: var(--accent-2);
}
.cle-top-btn:active {
  transform: scale(0.97);
}

.cle-badge {
  background: var(--amber);
  color: #000;
  border-radius: 4px;
  padding: 2px 5px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.cle-badge.connected {
  background: var(--ok);
  color: #fff;
}
.cle-badge.alert {
  background: var(--danger);
  color: #fff;
}

/* CLE Ribbon Bar under the main topbar */
#cle-ribbon {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--block-2);
  color: var(--block-ink);
  font: 12px/1 var(--f-ui);
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
  z-index: 100;
}
.cle-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: rgba(255, 255, 255, 0.08);
  padding: 3px 8px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.cle-group-label {
  font: 600 10px/1 var(--f-label);
  text-transform: uppercase;
  color: var(--ink-3);
  margin-right: 4px;
  letter-spacing: 0.05em;
}

.cle-btn {
  background: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 4px 8px;
  font: 500 11px/1.2 var(--f-ui);
